SIGNAL CLK2: STD_LOGIC;
SIGNAL CONTA: INTEGER RANGE 0 TO 21;
SIGNAL AUX2: INTEGER RANGE 0 TO 1249999;
SIGNAL CLK_ASM : STD_LOGIC;
SIGNAL VICTORY : STD_LOGIC := '0';

SIGNAL X1: INTEGER RANGE 0 TO 640 := 26;
SIGNAL X2: INTEGER RANGE 0 TO 640 := 34; 
