------------------------ CARTA ASM PARA CONTADOR -------------------------
TYPE EDOS IS (INICIO, IZQ, DER, ARR, ABA, RETARDO);
SIGNAL PRES: EDOS := INICIO;
SIGNAL RET: INTEGER RANGE 0 TO 100000 := 0;
SIGNAL AUX: INTEGER RANGE 0 TO 50;

SIGNAL DRAW1, DRAW2:STD_LOGIC;

BEGIN

	PROCESS(CLK_ASM, U, D, L, RR, DRAW1, DRAW2, VICTORY)
	BEGIN
		IF RISING_EDGE(CLK) THEN
			CASE PRES IS
				WHEN INICIO => IF DRAW1 = '1' AND DRAW2 = '1' THEN
--										X1 <= 280; X2 <= 320;
--										Y1 <= 200; Y2 <= 240;
--										X3 <= 290; X4 <= 310;
--										Y3 <= 180; Y4 <= 200;
--										
										X1 <= 26; X2 <= 34;
										Y1 <= 196; Y2 <= 198; 
										X3 <= 23; X4 <= 37; Y3 <= 198; Y4 <= 200;
										X5 <= 20; X6 <= 40; Y5 <= 200; Y6 <= 204;
										X7 <= 18; X8 <= 42; Y7 <= 204; Y8 <= 206;
										--X9 <= 19; --X10 <= 42; --Y9 <= 195; --Y10 <= 206;
										X11 <= 17; X12 <= 43; Y11 <= 206; Y12 <= 208;
										X13 <= 16; X14 <= 44; Y13 <= 208; Y14 <= 210; 
										X15 <= 12; X16 <= 48; Y15 <= 210; Y16 <= 220;
										X17 <= 16; X18 <= 44; Y17 <= 220; Y18 <= 223;
										X19 <= 18; X20 <= 42; Y19 <= 223; Y20 <= 225;
										X21 <= 17; X22 <= 43; Y21 <= 225; Y22 <= 226;
										X23 <= 16; X24 <= 44; Y23 <= 226; Y24 <= 227;
										X25 <= 15; X26 <= 45; Y25 <= 227; Y26 <= 230;
										X27 <= 16; X28 <= 30; Y27 <= 230; Y28 <= 232;
										X29 <= 17; X30 <= 29; Y29 <= 232; Y30 <= 234;
										X31 <= 31; X32 <= 44; Y31 <= 230; Y32 <= 232;
										X33 <= 32; X34 <= 43; Y33 <= 232; Y34 <= 234;
										PRES <= INICIO;
									ELSIF U = '0' THEN
										PRES <= ARR;
									ELSIF D = '0' THEN
										PRES <= ABA;
									ELSIF L = '0' THEN
										PRES <= IZQ;
									ELSIF RR = '0' THEN
										PRES <= DER;
									ELSE
										PRES <= INICIO;
									END IF;
									
--				WHEN DER => X1 <= X1 + 1; X2 <= X2 + 1;
--								X3 <= X3 + 1; X4 <= X4 + 1;
--								PRES <= RETARDO;
--							 
--				WHEN IZQ => X1 <= X1 - 1; X2 <= X2 - 1;
--				            X3 <= X3 - 1; X4 <= X4 - 1;
--							   PRES <= RETARDO;		
--						
--				WHEN ARR => Y1 <= Y1 + 1; Y2 <= Y2 + 1;
--								Y3 <= Y3 + 1; Y4 <= Y4 + 1;
--							   PRES <= RETARDO;
--				
--				WHEN ABA => Y1 <= Y1 - 1; Y2 <= Y2 - 1;
--								Y3 <= Y3 - 1; Y4 <= Y4 - 1;
--								PRES <= RETARDO;
				WHEN DER =>
				  X1 <= X1 + 1; X2 <= X2 + 1; 
				  X3 <= X3 + 1; X4 <= X4 + 1;
				  X5 <= X5 + 1; X6 <= X6 + 1;
				  X7 <= X7 + 1; X8 <= X8 + 1;
				  X11 <= X11 + 1; X12 <= X12 + 1;
				  X13 <= X13 + 1; X14 <= X14 + 1;
				  X15 <= X15 + 1; X16 <= X16 + 1;
				  X17 <= X17 + 1; X18 <= X18 + 1;
				  X19 <= X19 + 1; X20 <= X20 + 1;
				  X21 <= X21 + 1; X22 <= X22 + 1;
				  X23 <= X23 + 1; X24 <= X24 + 1;
				  X25 <= X25 + 1; X26 <= X26 + 1;
				  X27 <= X27 + 1; X28 <= X28 + 1;
				  X29 <= X29 + 1; X30 <= X30 + 1;
				  X31 <= X31 + 1; X32 <= X32 + 1;
				  X33 <= X33 + 1; X34 <= X34 + 1;
				  PRES <= RETARDO;

				WHEN IZQ =>
				  X1 <= X1 - 1; X2 <= X2 - 1;
				  X3 <= X3 - 1; X4 <= X4 - 1;
				  X5 <= X5 - 1; X6 <= X6 - 1;
				  X7 <= X7 - 1; X8 <= X8 - 1;
				  X11 <= X11 - 1; X12 <= X12 - 1;
				  X13 <= X13 - 1; X14 <= X14 - 1; 
				  X15 <= X15 - 1; X16 <= X16 - 1;
				  X17 <= X17 - 1; X18 <= X18 - 1;
				  X19 <= X19 - 1; X20 <= X20 - 1;
				  X21 <= X21 - 1; X22 <= X22 - 1;
				  X23 <= X23 - 1; X24 <= X24 - 1;
				  X25 <= X25 - 1; X26 <= X26 - 1;
				  X27 <= X27 - 1; X28 <= X28 - 1;
				  X29 <= X29 - 1; X30 <= X30 - 1;
				  X31 <= X31 - 1; X32 <= X32 - 1;
				  X33 <= X33 - 1; X34 <= X34 - 1;
				  PRES <= RETARDO;
					
				WHEN ARR =>
				  Y1 <= Y1 + 1; Y2 <= Y2 + 1;
				  Y3 <= Y3 + 1; Y4 <= Y4 + 1;
				  Y5 <= Y5 + 1; Y6 <= Y6 + 1; 
				  Y7 <= Y7 + 1; Y8 <= Y8 + 1;
				  Y11 <= Y11 + 1; Y12 <= Y12 + 1;
				  Y13 <= Y13 + 1; Y14 <= Y14 + 1;
				  Y15 <= Y15 + 1; Y16 <= Y16 + 1;
				  Y17 <= Y17 + 1; Y18 <= Y18 + 1;
				  Y19 <= Y19 + 1; Y20 <= Y20 + 1;
				  Y21 <= Y21 + 1; Y22 <= Y22 + 1;
				  Y23 <= Y23 + 1; Y24 <= Y24 + 1;
				  Y25 <= Y25 + 1; Y26 <= Y26 + 1;
				  Y27 <= Y27 + 1; Y28 <= Y28 + 1;
				  Y29 <= Y29 + 1; Y30 <= Y30 + 1;
				  Y31 <= Y31 + 1; Y32 <= Y32 + 1;
				  Y33 <= Y33 + 1; Y34 <= Y34 + 1;
				  PRES <= RETARDO;

				WHEN ABA =>
				  Y1 <= Y1 - 1; Y2 <= Y2 - 1;
				  Y3 <= Y3 - 1; Y4 <= Y4 - 1;
				  Y5 <= Y5 - 1; Y6 <= Y6 - 1;
				  Y7 <= Y7 - 1; Y8 <= Y8 - 1;  
				  Y11 <= Y11 - 1; Y12 <= Y12 - 1;
				  Y13 <= Y13 - 1; Y14 <= Y14 - 1;
				  Y15 <= Y15 - 1; Y16 <= Y16 - 1;
				  Y17 <= Y17 - 1; Y18 <= Y18 - 1;
				  Y19 <= Y19 - 1; Y20 <= Y20 - 1;
				  Y21 <= Y21 - 1; Y22 <= Y22 - 1;
				  Y23 <= Y23 - 1; Y24 <= Y24 - 1;
				  Y25 <= Y25 - 1; Y26 <= Y26 - 1;
				  Y27 <= Y27 - 1; Y28 <= Y28 - 1;
				  Y29 <= Y29 - 1; Y30 <= Y30 - 1;
				  Y31 <= Y31 - 1; Y32 <= Y32 - 1;
				  Y33 <= Y33 - 1; Y34 <= Y34 - 1;
				  PRES <= RETARDO;

								
				WHEN RETARDO => IF RET = 119999 THEN
							RET <= 0;
							PRES <= INICIO;
						ELSE
							RET <= RET + 1;
						END IF;
			END CASE;
	    END IF;
	END PROCESS;

    PROCESS(CLK, RST2, HPOS, VPOS, VIDEO) -- PROCESO PARA COLOREAR LOS PIXELES
    BEGIN
		IF RST2 = '1' THEN
            COLOR <= 2;
      	ELSIF FALLING_EDGE(CLK) THEN
			IF VICTORY = '1' THEN
				IF VIDEO = '1' THEN
					IF (HPOS >= 0 AND HPOS <= 639) AND (VPOS >= 0 AND VPOS <= 479) THEN
						IF CONTA = 2 THEN
							SAL <= ROM3(VPOS);
							PIX <= SAL(HPOS);
						ELSIF CONTA = 3 THEN
							SAL <= ROM4(VPOS);
							PIX <= SAL(HPOS);
						ELSIF CONTA = 4 THEN
							SAL <= ROM5(VPOS);
							PIX <= SAL(HPOS);
						ELSIF CONTA = 5 THEN
							SAL <= ROM6(VPOS);
							PIX <= SAL(HPOS);
						END IF;	
						IF PIX = '0' THEN
							COLOR <= 0;
						ELSE
							COLOR <= 1;
						END IF;
					ELSE
						COLOR <= 2;
					END IF;
				END IF;
			ELSE
				IF VIDEO = '1' THEN
					IF (HPOS >= X1 AND HPOS <= X2) AND (VPOS >= Y1 AND VPOS <= Y2) THEN
				 COLOR <= 3;
				 DRAW1 <= '1';
			ELSIF (HPOS >= X3 AND HPOS <= X4) AND (VPOS >= Y3 AND VPOS <= Y4) THEN
				 COLOR <= 3;
				 DRAW1 <= '1';
			ELSIF (HPOS >= X5 AND HPOS <= X6) AND (VPOS >= Y5 AND VPOS <= Y6) THEN
				 COLOR <= 3;
				 DRAW1 <= '1';
			ELSIF (HPOS >= X7 AND HPOS <= X8) AND (VPOS >= Y7 AND VPOS <= Y8) THEN
				 COLOR <= 3;
				 DRAW1 <= '1';
			ELSIF (HPOS >= X11 AND HPOS <= X12) AND (VPOS >= Y11 AND VPOS <= Y12) THEN
				 COLOR <= 3;
				 DRAW1 <= '1';
			ELSIF (HPOS >= X13 AND HPOS <= X14) AND (VPOS >= Y13 AND VPOS <= Y14) THEN
				 COLOR <= 3;
				 DRAW1 <= '1';
			ELSIF (HPOS >= X15 AND HPOS <= X16) AND (VPOS >= Y15 AND VPOS <= Y16) THEN
				 COLOR <= 3;
				 DRAW1 <= '1';
			ELSIF (HPOS >= X17 AND HPOS <= X18) AND (VPOS >= Y17 AND VPOS <= Y18) THEN
				 COLOR <= 3;
				 DRAW1 <= '1';
			ELSIF (HPOS >= X19 AND HPOS <= X20) AND (VPOS >= Y19 AND VPOS <= Y20) THEN
				 COLOR <= 3;
				 DRAW1 <= '1';
			ELSIF (HPOS >= X21 AND HPOS <= X22) AND (VPOS >= Y21 AND VPOS <= Y22) THEN
				 COLOR <= 3;
				 DRAW1 <= '1';
			ELSIF (HPOS >= X23 AND HPOS <= X24) AND (VPOS >= Y23 AND VPOS <= Y24) THEN
				 COLOR <= 3;
				 DRAW1 <= '1';
			ELSIF (HPOS >= X25 AND HPOS <= X26) AND (VPOS >= Y25 AND VPOS <= Y26) THEN
				 COLOR <= 3;
				 DRAW1 <= '1';
			ELSIF (HPOS >= X27 AND HPOS <= X28) AND (VPOS >= Y27 AND VPOS <= Y28) THEN
				 COLOR <= 3;
				 DRAW1 <= '1';
			ELSIF (HPOS >= X29 AND HPOS <= X30) AND (VPOS >= Y29 AND VPOS <= Y30) THEN
				 COLOR <= 3;
				 DRAW1 <= '1';
			ELSIF (HPOS >= X31 AND HPOS <= X32) AND (VPOS >= Y31 AND VPOS <= Y32) THEN
				 COLOR <= 3;
				 DRAW1 <= '1';
			ELSIF (HPOS >= X33 AND HPOS <= X34) AND (VPOS >= Y33 AND VPOS <= Y34) THEN
				 COLOR <= 3;
				 DRAW1 <= '1';

						
					--LABERINTO
					ELSIF (HPOS >= 0 AND HPOS <= 639) AND (VPOS >= 0 AND VPOS <= 479) THEN
						SAL <= ROM1(VPOS);
						PIX <= SAL(HPOS);
						IF PIX = '0' THEN
							COLOR <= 0;
							DRAW1 <= '0';
							DRAW2 <= '0';
						ELSIF PIX = '1' THEN
							COLOR <= 1;
							DRAW2 <= '1';
						END IF;
					ELSE
						COLOR <= 2;
						DRAW1 <= '0';
						DRAW2 <= '0';
					END IF;
				END IF;
			END IF;
        END IF;
	END PROCESS;


    PROCESS(CLK)
    BEGIN
        IF RISING_EDGE(CLK) THEN
            IF AUX2 = 0 THEN
                CLK2 <= NOT CLK2;
                AUX2 <= 1249999;
            ELSE
                AUX2 <= AUX2 - 1;
            END IF;
        END IF;
    END PROCESS;

    PROCESS(CLK2)
    BEGIN
		IF FALLING_EDGE(CLK2) THEN
			IF CONTA = 5 THEN
				CONTA <= 2;
			ELSE
				CONTA <= CONTA + 1;
			END IF;
		END IF;
    END PROCESS;

    WITH COLOR SELECT
        R <= "0000" WHEN 0,
              "1111" WHEN 1,
				  "1111" WHEN 3,
              "0000" WHEN OTHERS;
    WITH COLOR SELECT
        B <= "0000" WHEN 0,
              "1111" WHEN 1,
				  "0000" WHEN 3,
              "0000" WHEN OTHERS;
    WITH COLOR SELECT
        G <= "0000" WHEN 0,
              "1111" WHEN 1,
				  "0000" WHEN 3,
              "0000" WHEN OTHERS;

END BEAS;
